def specialize(template, recipe):
    data = METHODS.get(template['id'])
    if not data:
        recipe['method_status'] = '基础结构 · 待专门提炼'
        return recipe
    facts, proof, reveal, camera, light, sound, limits, applies = data
    recipe.update(version=2, description=proof+'；'+reveal+'。', method_status='专属制作方法',
                  applies_to=applies, inputs=['商品参考图与结构事实：'+facts, '唯一主张、目标受众及真实行动入口', '口播语言、人物出镜方式与需要避开的表达'],
                  references=['商品参考：约束'+facts, '环境参考：只借鉴空间层次、构图和光线，不能替代商品资料', '人物参考：出现人物或手部操作时补充身份与姿态，动作需与商品接触连续'],
                  adaptations=['适用：'+applies, limits, '替换原商品、场景与文案；依据新商品事实重新组织动作，不照搬原片镜头序列'],
                  steps=['准备：核对'+facts+'，未知信息写入待确认项',
                         '0–5 秒 · 吸引注意：'+proof,
                         '5–10 秒 · 证明细节：'+camera,
                         '10–15 秒 · 场景与归因：'+reveal,
                         '灯光与层次：'+light, '声音设计：'+sound,
                         '后期与检查：可读字幕由代码叠加，按所选模型和明确预算制作；逐项检查商品、动作、声音与行动入口'],
                  checks=['商品结构与参考一致：'+facts, '运镜和商品接触连续：'+camera,
                          '表达边界：'+limits, '声音与实际动作同步；没有把后期声音当作性能测试', '字幕可读、行动入口真实，内容待人工审阅'],
                  derivation={'basis':'published_storyboard', 'template_id':template['id'],
                              'note':'从已发布方案和场景描述提炼为新作方法；并非对样片运镜、音轨或效果的逐帧实测。'})
    return recipe
